INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('e5444dd8-80b1-590b-89c8-a41c28a5c4a7', '253ab84b-cde9-51ca-a335-bf2e720e7d51', 'en', $h$Diaphragm Pump$h$, $h$diaphragm-pump$h$, $h$Diaphragm Pump – Flexibility and Reliability in Industrial Liquid Transfer$h$, $h$<div> <p><strong>Diaphragm pumps</strong> are positive displacement pumps that transfer liquid without mechanical contact by means of an elastic diaphragm, delivering high efficiency and durability in industrial processes. They stand out for maintaining performance even with fluids containing dust, dirt and particles.</p><p>These pumps offer the ideal solution for the safe and controlled handling of <strong>high-viscosity, abrasive or contaminated liquids</strong>. They are designed to maximize liquid transfer line safety in marine and industrial environments.</p> </div><div> <p><strong>HD Marine diaphragm pumps</strong>;</p><ul><li>Provide highly efficient positive displacement for a <strong>more stable flow</strong></li><li>Deliver <strong>long-lasting performance</strong> when handling abrasive and contaminated liquids</li><li>Build confidence on your production line with a <strong>robust and durable construction</strong> suited to marine and industrial environments</li></ul> </div>$h$, $h$<div> <p>Diaphragm pumps are used particularly in:</p><ul><li>Chemical and petrochemical plants</li><li>Food and pharmaceutical production lines</li><li>Wastewater and filtration facilities</li><li>Paint, printing and solvent transfer applications</li><li>Marine machinery</li></ul><p>delivering reliable performance across a wide variety of industrial and marine applications.</p> </div>$h$, $h$Diaphragm Pump | HD Marine$h$, $h$Diaphragm pumps are positive displacement pumps that transfer liquid without mechanical contact by means of an elastic diaphragm, delivering high…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5b6b7aa4-b1b4-5ca7-980b-86143d45275e', 'a1f2922c-2b29-5af3-a1f2-37ea546d8294', 'en', $h$How does a diaphragm pump work?$h$, $h$<div> <p>Liquid is drawn in and discharged by the back-and-forth movement of a flexible diaphragm; there is no mechanical friction with the fluid.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('8152185f-4cc1-5487-af22-0dba70354d6c', '0ef27e6e-dc8f-5ed2-a7a7-84bc36089eda', 'en', $h$For which liquids is it preferred?$h$, $h$<div> <p>It is effective with particle-laden, abrasive, chemical or soluble liquids.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('cfa81648-df02-585f-b2b6-30ddbb82fb8d', '95309ff1-b960-57d1-bafc-29901a482bc1', 'en', $h$What is the difference between a diaphragm pump and a centrifugal pump?$h$, $h$<div> <p>Diaphragm pumps move liquid in a fixed volume via positive displacement, while centrifugal pumps convey the fluid using centrifugal force.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('a463d7f3-8fbe-5cc3-898d-c9e3b424f6b8', 'd0d30ee7-e267-5637-9d2a-343089fd5d18', 'en', $h$In which industries is it used in Turkey?$h$, $h$<div> <ul><li>It is common in chemical, paint and solvent, food and pharmaceutical, wastewater, marine and industrial facilities.</li></ul> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('85db65fb-1583-5ade-b123-28b4d4555393', '0de57938-4e61-5dce-9e4f-666656979eda', 'en', $h$Gear Pump$h$, $h$gear-pump$h$, $h$Gear Pump – Industrial Liquid Transfer Solutions$h$, $h$<div> <p><strong>Gear pumps</strong> are mechanical pumps that, thanks to their positive displacement operation, deliver a fixed amount of liquid per revolution and are frequently preferred in industrial systems. With these characteristics, they offer high performance and reliability, especially in the transfer of viscous (thick) liquids.</p><p>Gear pumps are the ideal solution for <strong>high-pressure transfer</strong>, <strong>low flow rate applications</strong> and <strong>systems requiring continuous flow control</strong>. By means of the gear wheels inside, these pumps draw in the liquid, pressurize it and deliver it steadily into the system line.</p><p>HD Marine gear pumps provide effectiveness in a variety of applications, from industrial facilities to production lines, with the capacity to transfer liquids across a wide viscosity range without problems.</p> </div><div> <p>✔ <strong>Constant flow rate:</strong> Delivers the same volume of liquid per revolution. <br/>✔ <strong>High viscosity compatibility:</strong> Suitable for oils, resins, chemicals and thick liquids. <br/>✔ <strong>High efficiency at low speed:</strong> Achieves the desired pressure and flow rate even at low motor speeds. <br/>✔ <strong>Reliable performance:</strong> Offers continuous and stable operation in industrial processes.</p> </div>$h$, $h$<div> <p>Gear pumps are used effectively in production facilities, chemical and petrochemical lines, lubrication systems, panel and hydraulic circuits, and in all industrial applications requiring viscous liquid transfer.</p> </div>$h$, $h$Gear Pump | HD Marine$h$, $h$Gear pumps are mechanical pumps that, thanks to their positive displacement operation, deliver a fixed amount of liquid per revolution and are frequently…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('e115a237-8b9b-5d7f-bdf4-13d5939871d8', '00597b28-bc2a-551b-a837-10d36a33ec60', 'en', $h$What is a gear pump used for?$h$, $h$<div> <p>Gear pumps draw in and discharge liquid at a fixed volume by means of gears, providing a smooth transfer.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c3fd8fd0-0c1b-58f5-800d-774440b2b858', 'b345ab44-23dd-57b8-a64a-664822710a70', 'en', $h$With which liquids is it used?$h$, $h$<div> <p>It is effective with oils, resins, chemical liquids and high-viscosity fluids.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('7cc5c6c7-ba7a-5de9-82e0-a80fe1a5f8b7', 'b13820c3-1c22-547c-857a-4d31f01fcd1b', 'en', $h$What is the difference between a gear pump and a centrifugal pump?$h$, $h$<div> <p>Gear pumps provide fixed-displacement flow; centrifugal pumps generate flow through pressure differential.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('b944c84b-388f-54cd-908e-99ed517a6b54', 'd5901428-7bb2-5759-aeb0-7732a64fb61b', 'en', $h$Blower$h$, $h$blower$h$, $h$Industrial Blower – Powerful Air & Gas Transfer Solutions$h$, $h$<div> <p>A <strong>blower</strong> is an industrial air <strong>blowing and vacuum device</strong> that draws in air or gas at high flow rates and within a specific pressure range and delivers it to the outlet. It plays an active role in applications such as oxygenation of industrial processes, ventilation, drying, supplying compressed air or gas evacuation. Blowers generate higher pressure and a more controllable flow rate than fans, which is why they are preferred in many fields such as HVAC, treatment plants, pneumatic conveying and process equipment.</p> </div><div> <p><strong>✔️ Why HD Marine Blowers?</strong></p><p>HD Marine blowers:</p><ul><li>Deliver <strong>energy-efficient performance</strong></li><li>Are durable with <strong>low vibration and long service life</strong></li><li>Offer suitable options for different <strong>flow rates and pressure levels</strong></li><li>Reduce operating costs with <strong>easy installation and maintenance</strong></li></ul><p>These characteristics make blowers a reliable solution within industrial air handling and process equipment.</p> </div><div> <p>✔ <strong>High air / gas flow rate:</strong> Provides large-volume airflow <br/>✔ <strong>Pressure boosting capacity:</strong> Generates higher pressure than fans <br/>✔ <strong>Air transfer and vacuum applications:</strong> Can be used in both blowing and suction directions <br/>✔ <strong>Motor-controlled air intake:</strong> Stable performance thanks to the electric motor<br/>✔ <strong>Various types:</strong> Compatible with centrifugal, rotary or positive displacement models <br/>✔ <strong>Durable housing:</strong> Suited to industrial operating conditions</p> </div>$h$, NULL, $h$Blower | HD Marine$h$, $h$A blower is an industrial air blowing and vacuum device that draws in air or gas at high flow rates and within a specific pressure range and delivers it…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('9dc18c89-b9d3-5da8-83c6-7b5ae9907e20', '0a5cc4ab-a5f1-59b5-b224-1a6c6c194ac4', 'en', $h$What is a blower?$h$, $h$<div> <p>A blower is an industrial air/gas transfer device that draws in air or gas at high flow rates and specific pressure values and delivers it to the outlet.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('fdc7c462-881f-5d94-a9a8-f2dfa4c4c738', '0b7a55a8-5048-5a01-89c5-054a9ce08b4e', 'en', $h$What is the difference between a blower and a fan?$h$, $h$<div> <p>Fans generally provide low-pressure air circulation, while blowers are performance-oriented with higher pressure and a controllable flow rate.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('93c844de-4d30-5083-8f2b-703ea6bf3064', '8d96907e-06a0-5227-84e6-401aa535cc4e', 'en', $h$In which applications is it used?$h$, $h$<div> <p>It is used in ventilation, pneumatic conveying, drying, wastewater treatment and marine air evacuation processes.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('fac4f249-eda2-5344-ac5a-418f62bedc12', '8ca628ba-7681-5d8f-8030-dfff77071760', 'en', $h$What should be considered when selecting a blower?$h$, $h$<div> <p>The required airflow, desired pressure level, ambient temperature and motor power are important criteria in blower selection.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('e06fe56e-7575-51b9-b85c-19b823f2754a', '94151aad-5d35-5bc5-b797-07b8775f2c27', 'en', $h$Magnetic Drive Acid Pumps$h$, $h$magnetic-drive-acid-pumps$h$, $h$Magnetic Drive Acid Pump – Reliable Transfer for Corrosive Liquids$h$, $h$<div> <p>Magnetic drive acid pumps are <strong>magnetically coupled positive displacement pumps specially built for handling acids, chemicals and corrosive liquids</strong>. By using a magnetic coupling instead of a mechanical seal, they maximize sealing performance and <strong>offer superior resistance to contaminants and abrasive fluids</strong>.</p><p>HD Marine magnetic drive acid pumps deliver <strong>high performance and durability</strong> across a wide range of uses, particularly <strong>from laboratories to production lines</strong>, from chemical plants to marine applications.</p> </div><div> <ul><li><p>✔ <strong>High chemical resistance:</strong> Operates with harsh liquids over long periods<br/>✔ <strong>Leak-free performance:</strong> Safe transfer thanks to the magnetic coupling<br/>✔ <strong>Easy installation:</strong> User-friendly mounting design<br/>✔ <strong>Long-life construction:</strong> High durability with minimal maintenance</p></li></ul> </div>$h$, $h$<div> <p>HD Marine magnetic drive acid pumps are an effective solution particularly in:</p><ul><li>Chemical production plants</li><li>Paint and solvent lines</li><li>Water and wastewater treatment</li><li>Acid/alkali transfer systems</li><li>Marine and industrial processes</li></ul><p>and in all applications <strong>requiring the safe handling of corrosive and abrasive fluids</strong>.</p> </div>$h$, $h$Magnetic Drive Acid Pumps | HD Marine$h$, $h$Magnetic drive acid pumps are magnetically coupled positive displacement pumps specially built for handling acids, chemicals and corrosive liquids . By…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('cf6cbcfe-5679-55be-967b-83081c197f44', 'e2b38441-f993-5429-820e-3dd9699be755', 'en', $h$What is a magnetic drive acid pump?$h$, $h$<div> <p>It is a magnetically coupled positive displacement pump that provides leak-free transfer by using a magnetic drive instead of a mechanical seal.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('829f019d-d509-5f7d-9945-73c0537480de', '04a0dd5d-dd6b-5f8e-9618-2500aea3e365', 'en', $h$Is it suitable for chemical liquids?$h$, $h$<div> <p>Yes, it has been developed for the transfer of acids, alkalis and chemical reaction liquids.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('fc435b67-71f2-5837-a071-2988eaf7e324', '8523b925-b1c8-5ad0-bbd4-031057225675', 'en', $h$Why is no packing used?$h$, $h$<div> <p>Thanks to the magnetic coupling, the need for packing is reduced, providing sealing and maintenance advantages.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('1bde2054-115f-5a81-a544-b0380a4dc883', '6c718d69-d859-506b-84d5-59fbac45353e', 'en', $h$Where should it be used?$h$, $h$<div> <p>It is preferred in chemical plants, water treatment, paint lines and industrial processes.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('426a0461-680f-5925-9907-ae54aaf1b89b', '8f6fe15a-82df-5840-bd1f-0374353b4006', 'en', $h$Drum Pump$h$, $h$drum-pump$h$, $h$Drum Pump – A Practical Solution for Industrial Liquid Transfer$h$, $h$<div> <p><strong>Drum pumps</strong> are industrial equipment that enable the fast, controlled and ergonomic transfer of liquids from drums, jerry cans and cylindrical storage tanks. They deliver ideal performance in the handling of oils, chemicals, solvents, fuels and other fluids.</p><p>HD Marine drum pumps, with their durable construction, easy installation and broad application compatibility, are a reliable liquid transfer solution in both industrial facilities and marine processes.</p> </div><div> <p>✔ <strong>Practical installation:</strong> Suitable for various drum diameters<br/>✔ <strong>Durable construction:</strong> Materials with high chemical and solvent resistance<br/>✔ <strong>Various drive options:</strong> Manual, electric or pneumatic operation<br/>✔ <strong>Easy to use:</strong> Fast transfer with an ergonomic pump design<br/>✔ <strong>Broad application compatibility:</strong> Transfer of oil, fuel, chemicals, acids and alkalis</p> </div>$h$, NULL, $h$Drum Pump | HD Marine$h$, $h$Drum pumps are industrial equipment that enable the fast, controlled and ergonomic transfer of liquids from drums, jerry cans and cylindrical storage…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('48afea4d-efd2-5c98-9128-a0884291c337', '5dbaab34-afd1-531c-8166-d0e7ca651ab9', 'en', $h$What is a drum pump?$h$, $h$<div> <p>A drum pump is a special transfer pump that can dispense liquids from drums, jerry cans and tanks in an ergonomic and controlled manner.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('834326b0-66c3-5a3e-8de1-d37f1649a17d', '051d3b1c-196f-553f-9b22-98bfb7353b9b', 'en', $h$With which liquids can it be used?$h$, $h$<div> <p>Suitable models are available for oils, chemicals, solvents, fuels and various fluid types.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('4f927d11-7c76-573a-8375-eeda52c8c361', '0c9e1a01-b473-50cb-a9a3-5b496c1dacba', 'en', $h$What is the advantage of an electric drum pump?$h$, $h$<div> <p>Electric models provide faster transfer with less effort; they are suitable for large-volume storage.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('b993aef7-3242-5763-b72f-87d8ac603e57', '467085c4-2d6b-5767-8bd9-364c6770fbce', 'en', $h$How is the pump material selected?$h$, $h$<div> <p>The body and gasket materials (PP, aluminum, stainless steel, Viton, etc.) should be selected according to the chemical nature of the liquid to be handled.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('2cd7692c-4360-5aa1-9a49-065b9bf674ca', 'dafeaf56-2575-5e8d-82f5-c1a62bf5b04a', 'en', $h$Vacuum Pump$h$, $h$vacuum-pump$h$, $h$Vacuum Pump – A Powerful Solution for Effective Air/Void Control$h$, $h$<div> <p><strong>Vacuum pumps</strong> create negative pressure in a system by extracting the air or gas molecules within it. In this way, they deliver reliable performance in critical industrial applications such as <strong>creating a vacuum environment, gas evacuation and discharging ambient air</strong>. They are widely used in industry, chemicals, laboratories, production lines, packaging and process control systems.</p><p>HD Marine vacuum pumps, with their durable construction, precise suction power and high efficiency, <strong>deliver effective results even under continuous operating conditions.</strong></p> </div><div> <p>✔ <strong>High suction capacity:</strong> Stable and fast evacuation<br/>✔ <strong>Energy saving:</strong> Low energy consumption in long-term use<br/>✔ <strong>Broad compatibility:</strong> Integrates with different industry types<br/>✔ <strong>User-friendly design:</strong> Easy installation and maintenance</p> </div>$h$, $h$<div> <p>HD Marine vacuum pumps are suitable particularly for:</p><ul><li>Industrial process lines</li><li>Laboratory applications</li><li>Packaging machines</li><li>Chemical plants</li><li>HVAC and drying systems</li><li>Electronics production lines</li></ul><p>and other <strong>processes requiring gas evacuation or a vacuum environment</strong>.</p> </div>$h$, $h$Vacuum Pump | HD Marine$h$, $h$Vacuum pumps create negative pressure in a system by extracting the air or gas molecules within it. In this way, they deliver reliable performance in…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('e2377fe2-248f-5b1e-b9b3-84c6955028ba', 'd2a4f83b-27ee-5193-aa3e-20a6a11b7e91', 'en', $h$What is a vacuum pump?$h$, $h$<div> <p>A vacuum pump creates negative pressure by extracting air or gases from a system, providing a vacuum environment.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('1941a781-b560-5b6d-b897-2cd77417a363', '16db7546-bb0f-5158-b7ef-b45226a0a79f', 'en', $h$In which industries is it used?$h$, $h$<div> <p>It is widely used in industry, laboratories, production lines, packaging and chemical plants.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('a9e53e04-3b56-5362-9a92-7c29d2cfbbb6', 'b0dbb3e9-490b-55cd-a658-627f4ac38f89', 'en', $h$What is the difference between a vacuum pump and a pressure pump?$h$, $h$<div> <p>A vacuum pump draws air by creating negative pressure, whereas a pressure pump pushes the fluid.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d85fef8a-dd56-5c22-9102-6096c3779075', 'e33f2e87-834a-5d05-90f0-c6c8f495f4b8', 'en', $h$How often should a vacuum pump be maintained?$h$, $h$<div> <p>Periodic oil changes and leak checks are recommended depending on operating conditions.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('c4e3b252-d280-51ba-bda9-06e4b509510a', 'aa6ce44f-15fa-545f-b6b8-6a15f304eb00', 'en', $h$Dosing Pump$h$, $h$dosing-pump$h$, $h$Dosing Pump – A Precise and Reliable Liquid Dosing Solution$h$, $h$<div> <p><strong>Dosing pumps</strong> are high-precision industrial pumps designed to add a specific fluid to a system <strong>at a defined ratio and flow rate</strong>. They are frequently used in water treatment, chemicals, food production, wastewater processing and process control applications. Thanks to accurate dosing capability, they <strong>raise the quality of the manufactured product, reduce costs and increase process efficiency.</strong></p><p>HD Marine dosing pumps, with their <strong>adjustable flow control and durable construction</strong>, deliver stable and repeatable performance in industrial systems of every scale.</p> </div><div> <p>✔ <strong>High precision:</strong> Top-level consistency in the measured liquid quantity<br/>✔ <strong>Energy efficiency:</strong> Low energy consumption in long-term use<br/>✔ <strong>Easy maintenance:</strong> Fast servicing thanks to its modular design<br/>✔ <strong>Broad application compatibility:</strong> Flexible use for many industrial processes</p> </div>$h$, $h$<div> <p>HD Marine dosing pumps are used reliably in the following sectors:</p><ul><li><strong>Water and wastewater treatment plants</strong></li><li><strong>Chemical and petrochemical industry</strong></li><li><strong>Food and beverage production</strong></li><li><strong>Dyeing and textile processes</strong></li><li><strong>Heating, cooling and HVAC systems</strong></li><li><strong>Industrial process automation</strong></li></ul><p>These pumps deliver high accuracy in all applications requiring controlled and continuous dosing.</p> </div>$h$, $h$Dosing Pump | HD Marine$h$, $h$Dosing pumps are high-precision industrial pumps designed to add a specific fluid to a system at a defined ratio and flow rate . They are frequently used…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c5f02ccb-50c9-5738-a988-6bd387f78053', 'bf9e337c-8d98-5214-8e62-0681c7b96ac4', 'en', $h$How does a diaphragm pump work?$h$, $h$<div> <p>A dosing pump is used to add a specific volume of liquid to a system in a controlled and adjustable manner.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d57939cc-c841-5ee5-8da3-6ccd1007f608', 'ac7f5894-09b2-5e43-acf3-646c592cee98', 'en', $h$In which sectors is it preferred?$h$, $h$<div> <p>It is widely used in water treatment, chemical production, food and beverage lines, wastewater and process control applications.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('63f1f1a5-aa8b-5ae7-bba0-3a700f2a6d8b', '62807921-7499-5ff7-8443-035b48b19ef3', 'en', $h$What is the difference between a dosing pump and a diaphragm pump?$h$, $h$<div> <p>A dosing pump is optimized for precise and adjustable liquid addition, while a diaphragm pump provides general positive displacement transfer.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('6a2927bb-27c5-5b05-b6e1-df4fb8a68de5', '0cb3652d-d4ed-5f21-9087-f6608c5b19ff', 'en', $h$How is the flow rate adjusted?$h$, $h$<div> <p>The desired flow rate can easily be selected via the control panel and adjustment knobs.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('a6a3814d-ffc2-5c78-85d4-2e1a94da1385', 'ee21040f-bed2-5a1d-bf45-784cfd019609', 'en', $h$Mono Pump$h$, $h$mono-pump$h$, $h$Mono Pump – Industrial Single-Stage Liquid Pump Solution$h$, $h$<div> <p>A <strong>mono pump</strong> is a type of <strong>single-stage centrifugal pump</strong> generally used in industrial facilities. It stands out with highly efficient liquid transfer, a simple design and low maintenance requirements. Mono pump models deliver reliable performance particularly in the handling of <strong>water, chemical solutions, oil and other fluids</strong>.</p><p>HD Marine mono pumps are a powerful aid in industrial processes thanks to their compact design, durable construction and <strong>high operating efficiency</strong>.</p> </div><div> <p>HD Marine mono pumps offer effective solutions in the following areas:</p><ul><li><strong>Water supply and discharge systems</strong></li><li><strong>Chemical transfer applications</strong></li><li><strong>Cooling systems</strong></li><li><strong>Paint and textile processes</strong></li><li><strong>Machine and equipment circuits</strong></li></ul><p>In these applications, the mono pump provides efficient and continuous liquid flow, contributing to the uninterrupted operation of processes.</p> </div><div> <p>📌 <strong>High efficiency:</strong> Effective energy use with a single-stage design</p><p>🛠 <strong>Easy maintenance:</strong> Servicing is simple and fast</p><p>🔧 <strong>Durability:</strong> Long-life construction with low operating costs</p><p>⚙ <strong>Various flow rate options:</strong> Wide capacity range from small to medium scale</p> </div>$h$, NULL, $h$Mono Pump | HD Marine$h$, $h$A mono pump is a type of single-stage centrifugal pump generally used in industrial facilities. It stands out with highly efficient liquid transfer, a…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d43917e4-ec19-5ff9-a635-e7d00bf9f709', 'cb553f18-f1e7-56c9-a4c3-535c3f9874aa', 'en', $h$What is a mono pump?$h$, $h$<div> <p>A mono pump is a liquid transfer pump operating on a single-stage centrifugal principle.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('6f5b0c58-bf41-5ee7-921e-913aefc3d330', 'd281d5ee-5e61-569b-9d92-36354f2995c8', 'en', $h$With which liquids is it used?$h$, $h$<div> <p>It is ideal for the transfer of fluids such as water, light chemical solutions, cooling and process water.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('959f3dbf-0ceb-543a-9954-7dd33370e5c1', '26ebb686-1a70-5558-8dc9-9b0fcef5df24', 'en', $h$What is the advantage of a mono pump?$h$, $h$<div> <p>Thanks to its simple design, it provides low maintenance requirements, high efficiency and durability.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('6c351489-4e12-5ba2-ae53-f332b5de6c38', '1263ce17-69af-5de0-99eb-7f1148fc4c36', 'en', $h$Who should choose it?$h$, $h$<div> <p>It is suitable for factories, industrial facilities, water transfer systems and process applications.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('f191018d-c864-51b9-a135-3b40abc83593', '58eca827-e60d-52b8-b970-af35ad0d0560', 'en', $h$Spiral Wound Steel Gasket$h$, $h$spiral-wound-steel-gasket$h$, $h$Spiral Wound Steel Gasket – Heavy-Duty Sealing Solution$h$, $h$<div> <p><strong>Spiral wound steel gaskets</strong> are industrial sealing elements that deliver <strong>superior sealing performance</strong> in high-pressure, high-temperature and demanding operating environments. The steel spiral winding structure, containing elastomer or graphite filler material, offers <strong>high strength, flexibility and recompression capability</strong>.</p><p>HD Marine spiral wound steel gaskets deliver long-lasting and reliable performance at <strong>flange connections</strong>, <strong>pipelines</strong>, <strong>pressure vessels</strong>, <strong>valves</strong> and other critical sealing points.</p> </div><div> <p>✔ <strong>High pressure resistance:</strong> Effective in heavy-duty applications<br/>✔ <strong>High temperature tolerance:</strong> Performance up to ±540°C<br/>✔ <strong>Mechanical strength:</strong> Superior resistance with a steel-wound structure<br/>✔ <strong>Flexible adaptation:</strong> Tolerates flange surface irregularities<br/>✔ <strong>Wide range of applications:</strong> Oil, chemical, energy and shipboard facilities</p> </div>$h$, $h$<div> <p>Spiral wound steel gaskets are used particularly in:</p><ul><li><strong>High-pressure pipelines</strong></li><li><strong>Steam and heat systems</strong></li><li><strong>Critical flange connections</strong></li><li><strong>Valve and pump bodies</strong></li><li><strong>Oil, chemical and energy plants</strong></li><li><strong>Ship and marine applications</strong></li></ul><p>and other industrial environments <strong>requiring high strength and sealing performance</strong>.</p> </div>$h$, $h$Spiral Wound Steel Gasket | HD Marine$h$, $h$Spiral wound steel gaskets are industrial sealing elements that deliver superior sealing performance in high-pressure, high-temperature and demanding…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('ab11d978-ce90-5ce4-a4c6-2956935cbd50', 'ac4b029f-02ee-5028-a858-4aa0379f453c', 'en', $h$What is a spiral wound steel gasket?$h$, $h$<div> <p>A spiral wound steel gasket is an industrial gasket that provides sealing at high pressure through a steel wire spiral structure and elastomer / graphite filler.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('eb81cf97-3e08-5ac8-89c8-ac853578fffa', '45c335ce-cbb2-5409-912b-d69e32a70f88', 'en', $h$In which applications is it used?$h$, $h$<div> <p>It is preferred in flange connections, pipelines, valves, pressurized systems and high-temperature applications.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('3e4f141e-9725-5e7d-924e-4da91a809228', 'ffe0ce1a-4ce4-5235-9705-f879c84ca453', 'en', $h$What does the graphite filler do?$h$, $h$<div> <p>The graphite filler provides high temperature and chemical resistance, and increases the gasket's flexible adaptation.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('b87cb07e-a41b-563c-9b84-80ba2504402d', '20593174-28d9-5f31-9d10-4f339aed7dff', 'en', $h$Why is the steel material type important?$h$, $h$<div> <p>Stainless steels such as AISI 304 and AISI 316 provide long life and resistance in corrosive environments.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('f873bafb-f0ea-520d-98be-cdee61b22adb', '5992167a-bbd3-580f-8470-ac9929c461ec', 'en', $h$Graphite and Klingerite Gaskets$h$, $h$graphite-and-klingerite-gaskets$h$, $h$Graphite & Klingerite Gaskets – High-Performance Sealing Elements$h$, $h$<div> <p><strong>Graphite and klingerite gaskets</strong> are critical sealing solutions used in pipelines, flange connections, valves and industrial equipment to provide <strong>sealing against high temperature, high pressure and aggressive chemicals</strong>. These gaskets are manufactured from special graphite alloy materials and fiber-reinforced compositions, and deliver reliable performance in demanding processes.</p><p>Graphite gaskets are produced from pure or reinforced graphite material and are preferred particularly in high-heat, steam, oil, water and gas applications. This structure gives the material both <strong>high chemical resistance</strong> and <strong>temperature tolerance</strong>.</p><p>Klingerite gaskets are typically formed by pressing graphite- or fiber-based mixtures, and provide sealing to industrial standards with asbestos-free options.</p> </div><div> <p>✔ <strong>High temperature resistance</strong> – Suitable for steam and superheated environments (performance over a wide temperature range) <br/>✔ <strong>Strong sealing against pressure</strong> – Creates an effective seal at flange, valve and pipe joint connections <br/>✔ <strong>Chemical resistance</strong> – Resistant to oils, acids, alkaline solutions and solvents <br/>✔ <strong>Flexible conformity</strong> – Fills surface irregularities for effective gasket performance <br/>✔ <strong>Asbestos-free production</strong> – Manufactured with alternatives that meet modern sealing requirements and are harmless to human health</p> </div>$h$, $h$<div> <p>Graphite and klingerite gaskets are used effectively in the following applications:</p><ul><li>Flange connections and pipelines</li><li>Valve covers and pump bodies</li><li>Steam systems and high-temperature processes</li><li>Chemical, petrochemical and energy plants</li><li>Marine and industrial piping circuits</li></ul><p>These gaskets are sealing elements preferred particularly for <strong>high temperature, high pressure and aggressive environments</strong>.</p> </div>$h$, $h$Graphite and Klingerite Gaskets | HD Marine$h$, $h$Graphite and klingerite gaskets are critical sealing solutions used in pipelines, flange connections, valves and industrial equipment to provide sealing…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('b8e6be5b-3421-56fd-bce2-eba81c1a0421', '14ed46ed-c461-597c-ac43-cbedb3ac3d5b', 'en', $h$What is a graphite gasket?$h$, $h$<div> <p>A graphite gasket is a graphite-based gasket type that provides effective sealing at high temperature and pressure; it is resistant to aggressive chemicals.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('b0babc48-830b-51fe-add6-ab7a50678ca2', '2c524bae-c97a-54a8-8b66-a201ab5bd999', 'en', $h$What is a klingerite gasket used for?$h$, $h$<div> <p>Klingerite gaskets are formed from a mixture of graphite and fiber, and provide reliable sealing at flange, valve and pipe connections.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('eb5408bc-c450-51c6-b0e8-9f4e8cf39896', '04bb980b-0724-531e-9381-c2db9eb9a236', 'en', $h$In which sectors is it used?$h$, $h$<div> <p>It is widely used in chemicals, energy, petrochemicals, shipping, steam lines and general industrial processes.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d32c4923-fbe2-51fc-ade0-ff941c6e7101', 'f986861f-9f9f-5337-80a7-cf8ca2f722de', 'en', $h$What is the difference between a graphite gasket and a standard gasket?$h$, $h$<div> <p>Graphite gaskets provide high temperature and chemical resistance; standard gaskets are for lower-performance environments.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('76065fc3-ae66-5c40-a7db-a9b5755db22e', '95a3a6fc-96f1-52ed-b228-95262bfd989d', 'en', $h$Teflon and Self-Adhesive Teflon Gasket$h$, $h$teflon-and-self-adhesive-teflon-gasket$h$, $h$Teflon & Self-Adhesive Teflon Gaskets – High-Performance Sealing Elements$h$, $h$<div> <p><strong>Teflon gaskets (PTFE gaskets)</strong> and <strong>self-adhesive Teflon gaskets</strong> are high-performance sealing elements used to provide <strong>high chemical resistance, low friction and excellent sealing</strong> at industrial pipelines, valve connections, pump bodies and various mechanical assembly points.</p><p>Since PTFE material is resistant to chemicals, high temperatures and abrasive environments, these gaskets are preferred particularly in <strong>applications involving aggressive fluids</strong>. Self-adhesive Teflon gaskets additionally offer <strong>easy positioning</strong> during application and a <strong>fast installation advantage</strong>.</p> </div><div> <p>✔ <strong>High chemical resistance:</strong> Resistant to acids, alkalis and aggressive fluids<br/>✔ <strong>Wide temperature tolerance:</strong> Safe use from -200°C up to +260°C<br/>✔ <strong>Low friction:</strong> Minimized during installation and use<br/>✔ <strong>Easy installation (self-adhesive):</strong> Practical application with a self-adhesive surface<br/>✔ <strong>Long service life:</strong> High-performance and durable PTFE material</p> </div>$h$, $h$<div> <p>HD Marine Teflon and Self-Adhesive Teflon gaskets provide effective sealing in the following applications:</p><ul><li>Industrial pipe and flange connections</li><li>Chemical and petrochemical plants</li><li>Abrasive chemical transfer lines</li><li>Shipboard marine systems</li><li>Processes requiring high temperature/chemical resistance</li></ul><p>These gaskets provide reliable and long-lasting sealing, particularly in <strong>circuits where chemicals are conveyed</strong>.</p> </div>$h$, $h$Teflon and Self-Adhesive Teflon Gasket | HD Marine$h$, $h$Teflon gaskets (PTFE gaskets) and self-adhesive Teflon gaskets are high-performance sealing elements used to provide high chemical resistance, low…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('91b6711c-6cee-59b7-b8f8-b6b4402a04e3', '4cba1f47-1f16-54f0-a800-5aa0c5cdead2', 'en', $h$What is a Teflon gasket?$h$, $h$<div> <p>A Teflon gasket is a sealing element made from PTFE material, providing high chemical resistance and low friction.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5bb65626-3a69-5f1b-8831-5dd027da8494', '71c69d49-eab4-5103-bd53-b1e4bee9b7f2', 'en', $h$What is a self-adhesive Teflon gasket used for?$h$, $h$<div> <p>The self-adhesive Teflon gasket is designed for easy positioning on slippery surfaces during installation and fast setup.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('703ea36f-7566-5667-a05f-509122ee10d7', '3f60d539-a57c-5cb1-a8a3-ff6e98263644', 'en', $h$In which applications is it preferred?$h$, $h$<div> <p>It is preferred in chemical plants, pipe flanges, valve connections, pump bodies and aggressive fluid circuits.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('cbf53722-a024-533c-821e-6aecd25b0fb4', 'fce488e2-077e-5a85-9743-bbc2e9b0bdd3', 'en', $h$What is the temperature resistance of a Teflon gasket?$h$, $h$<div> <p>Teflon gaskets are durable across a wide temperature range from -200°C to +260°C.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('0d1e975a-5cfd-5dbb-80e2-3f8f293d0b1f', 'a201e609-01d4-588c-b4b8-2ebafa6f8669', 'en', $h$Soft Packings$h$, $h$soft-packings$h$, $h$Soft Packings – High Sealing Performance and Durability$h$, $h$<div> <p><strong>Soft packings</strong> are elastic sealing elements that provide <strong>sealing and mechanical isolation</strong> by closing the gap between the shaft and the housing. They are widely used in pipeline systems, pumps, valves, rotor shaft connections and industrial mechanisms to prevent leaks of water, oil, fuel and various fluids.</p><p>HD Marine soft packings deliver long-lasting performance with their <strong>flexible structure, high chemical compatibility and durable material</strong>.</p> </div><div> <p>✔ <strong>Superior sealing:</strong> Effectively prevents liquid and gas leaks<br/>✔ <strong>Flexible and conformable:</strong> Full seating on the shaft surface and stretching capability<br/>✔ <strong>Chemical resistance:</strong> Resistance to water, oil, fuel and mild chemicals<br/>✔ <strong>Low friction:</strong> Minimizes wear<br/>✔ <strong>Easy installation:</strong> Practical and fast setup</p> </div>$h$, $h$<div> <p>HD Marine soft packings provide <strong>sealing and long-life performance</strong> particularly in:</p><ul><li>Industrial <strong>pump and valve shafts</strong></li><li><strong>Pipelines</strong> and process circuits</li><li>Marine and shipping applications</li><li>Engine rooms and mechanical systems</li><li>Pressurized system connections</li></ul><p>and similar operations.</p> </div>$h$, $h$Soft Packings | HD Marine$h$, $h$Soft packings are elastic sealing elements that provide sealing and mechanical isolation by closing the gap between the shaft and the housing. They are…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('da872a7f-44f1-59f7-b046-21172acee9c4', 'fc718e63-4041-52c4-8c70-5120dc3b07df', 'en', $h$What is a soft packing?$h$, $h$<div> <p>A soft packing is a flexible sealing element that prevents liquid or gas leaks by closing the gaps between the shaft and the hub.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('f41cfeeb-f4a3-5178-8e1d-f0ddf89ee473', '7ff03678-077f-539e-a9d6-70f6ab81c46d', 'en', $h$From which materials is it made?$h$, $h$<div> <p>It is generally produced from NBR, Viton, neoprene or elastomer compounds; the choice depends on the application.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c2ac6913-9d5a-5f6a-af09-652e64347bae', 'e8f6d425-13b9-5820-af77-80dbfb90de1c', 'en', $h$Where is it used?$h$, $h$<div> <p>It is used on pump shafts, valves, rotor connections and process piping.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('1f37ba69-cc44-55b6-8370-15995a195bed', '9603b7c1-fe40-529b-bdca-16ae37023682', 'en', $h$What is its temperature resistance?$h$, $h$<div> <p>Depending on the material, it can withstand temperatures in the range of -40°C to +120°C.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('bd568d9c-0754-5b9c-9ee2-3527d56a4c20', '15d6e92a-fc27-58f7-9f04-75b237090ebd', 'en', $h$Hatch Cover Tapes$h$, $h$hatch-cover-tapes$h$, $h$Hatch Cover Tapes – Marine and Industrial Sealing Solution$h$, $h$<div> <p><strong>Hatch cover tapes</strong> are special tapes designed to <strong>provide sealing and insulation for hatch covers</strong> on ships, marine vessels and industrial facilities. They are resistant to vibration, water or oil contact occurring during operation, and by forming an effective barrier at cover joints they <strong>prevent water ingress, smoke passage and corrosion.</strong></p><p>HD Marine hatch cover tapes provide reliable sealing in both the marine and industrial sectors with their long-lasting flexible structure and high resistance.</p> </div><div> <p>✔ <strong>High sealing performance:</strong> Effective barrier against water, oil, dust and contamination<br/>✔ <strong>Flexible and durable material:</strong> Adapts to vibration and temperature changes<br/>✔ <strong>Easy application:</strong> Fast installation in tape form<br/>✔ <strong>Resistance to UV and weather conditions:</strong> Long life in marine and outdoor environments<br/>✔ <strong>Wide range of use:</strong> Hatch covers, valve covers, door/frame sealing</p> </div>$h$, $h$<div> <p><strong>Hatch cover tapes provide high resistance and reliable sealing, particularly in:</strong></p><ul><li>Hatch cover sealing on ships</li><li>Cover and frame insulation on marine vessels</li><li>Industrial cover, valve and panel connections</li><li>Applications preventing water and oil passage</li><li>Sealing on vibrating surfaces</li></ul><p>and similar applications.</p> </div>$h$, $h$Hatch Cover Tapes | HD Marine$h$, $h$Hatch cover tapes are special tapes designed to provide sealing and insulation for hatch covers on ships, marine vessels and industrial facilities. They…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('55bde08f-5663-5501-9de1-6c3cffc7b8b3', '2f58a222-e5ce-5b6b-adba-33441227e82e', 'en', $h$What is a hatch cover tape?$h$, $h$<div> <p>A hatch cover tape is a sealing material that prevents the ingress of water, air and contamination at cover and frame joints.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('018079a3-a085-57e2-9e78-27143b360241', '99a81e44-d386-5a12-9cc2-1876ecbca7a0', 'en', $h$With which materials is it compatible?$h$, $h$<div> <p>It has an elastomeric structure compatible with most metals, plastics, composites and marine surfaces.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('f93054f8-29f5-5bfa-b3f9-ab4ff392c242', '8ff32215-88ce-560f-8284-864dafa6c421', 'en', $h$How is it applied?$h$, $h$<div> <p>After the surface is cleaned, a tape of suitable width is selected and applied; the adhesive surface is reinforced.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('b962579f-bad1-59fa-a45b-0c4479719e79', '10b49bd1-2c87-557a-8655-8bac1f7b8958', 'en', $h$Is it durable in a marine environment?$h$, $h$<div> <p>Yes, it is manufactured with material resistant to UV, salt water and weather conditions.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('84207006-31b0-56b1-ab44-cf540fbe519d', 'fd82ac1d-3c38-5447-8efc-b43f460caf61', 'en', $h$Pipe Repair Clamps$h$, $h$pipe-repair-clamps$h$, $h$Pipe Repair Clamps – Fast and Reliable Pipe Repair Solution$h$, $h$<div> <p><strong>Pipe repair clamps</strong> are connection elements used to <strong>repair damage such as leaks, cracks or holes in pipes quickly, practically and safely</strong>. They save time and money by returning piping systems to service across different application areas, from industrial facilities to marine lines.</p><p>HD Marine pipe repair clamps, with their durable construction, quality materials and easy installation advantage, provide an effective solution for <strong>water, oil, fuel and other fluid lines</strong>.</p> </div><div> <p>✔ <strong>Fast installation:</strong> Simply tighten the bolts<br/>✔ <strong>Suitable for various pipe diameters:</strong> From 15 mm up to 500 mm<br/>✔ <strong>Durable gasket:</strong> Broad fluid compatibility with EPDM / NBR options<br/>✔ <strong>High pressure resistance:</strong> Suitable for industrial lines<br/>✔ <strong>Corrosion resistance:</strong> Galvanized or stainless options</p> </div>$h$, $h$<div> <ul><li>Industrial process piping</li><li>Marine machinery and line systems</li><li>Water and wastewater facilities</li><li>Fuel and oil transfer lines</li><li>Chemical pipelines</li></ul><p>Pipe repair clamps provide a fast and economical solution for stopping a pipeline failure or making a temporary repair.</p> </div>$h$, $h$Pipe Repair Clamps | HD Marine$h$, $h$Pipe repair clamps are connection elements used to repair damage such as leaks, cracks or holes in pipes quickly, practically and safely . They save time…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('52933371-ebd7-5ed8-be3f-0e007f47ab20', '0f148a81-d430-5d53-8c44-d557865730ec', 'en', $h$What is a pipe repair clamp?$h$, $h$<div> <p>A pipe repair clamp is a connection element used to close leaks, cracks and holes in pipelines quickly and practically.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d9012be7-2664-556a-9de1-fc65d178d585', '061a0eef-c760-512e-b93e-2cb2e525c6af', 'en', $h$For which pipe diameters is it used?$h$, $h$<div> <p>It can be used on pipelines of various diameters from 25 mm up to 300 mm.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('993b3194-d387-5f7f-9bc9-c353f84bd3d9', '0f8f591f-51bc-5dc5-b70a-fbb792d95e1d', 'en', $h$For which fluids is it suitable?$h$, $h$<div> <p>With its durable gasket and material, it is suitable for different fluid lines such as water, oil, fuel and chemicals.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('91ec7d3a-8e03-5dd3-bd7a-8434626a3695', '96481a3c-8428-5c0f-b4e5-eff02323331e', 'en', $h$Is installation difficult?$h$, $h$<div> <p>No. Thanks to the bolted system, it provides fast and easy installation.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('154c7e07-9d3c-5dd2-ac53-28b052248938', 'ad803e91-7fdc-522a-8463-09137fb264f2', 'en', $h$Pipe Repair Bandage$h$, $h$pipe-repair-bandage$h$, $h$Pipe Repair Bandage – A Practical and Permanent Repair Solution$h$, $h$<div> <p>A <strong>pipe repair bandage</strong> is an <strong>after-production repair bandage</strong> used to quickly repair damage such as cracks, tears or abrasions in pipelines. Thanks to its elastic and durable structure, it enables pipes that will not close, are leaking or have been damaged to return to service in a short time.</p><p>HD Marine pipe repair bandages offer an effective repair solution in marine, industrial and infrastructure applications with their <strong>high strength</strong>, <strong>corrosion resistance</strong> and <strong>long service life</strong>.</p> </div><div> <p>✔ <strong>Fast application:</strong> Applied practically by wrapping<br/>✔ <strong>Durable material:</strong> High strength with fiberglass + epoxy<br/>✔ <strong>Suitable for various pipe diameters:</strong> Use from 25 to 250 mm<br/>✔ <strong>High pressure resistance:</strong> Suitable for industrial facilities<br/>✔ <strong>Corrosion resistance:</strong> Resistant to fluids such as water, oil and chemicals</p> </div><div> <p><strong>🛠️ Where Is It Used?</strong></p><p>HD Marine pipe repair bandages provide reliable and fast solutions for <strong>leak and damage repair</strong> particularly in:</p><ul><li>Water and wastewater lines</li><li>Fuel and oil transfer pipes</li><li>Industrial process lines</li><li>Marine and engine room applications</li><li>Chemical line repairs</li></ul><p>and other different sectors.</p> </div>$h$, NULL, $h$Pipe Repair Bandage | HD Marine$h$, $h$A pipe repair bandage is an after-production repair bandage used to quickly repair damage such as cracks, tears or abrasions in pipelines. Thanks to its…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('05d4c8c5-3a0e-568f-bf0b-98a370465195', '97ce1a11-a4d7-51d1-96a0-2770fa02fa3d', 'en', $h$What is a pipe repair bandage?$h$, $h$<div> <p>A pipe repair bandage is a reinforcement bandage used to repair cracked or damaged pipelines in a practical and durable way.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('af170fb7-a446-5a83-b50a-ca520c421317', '38984016-c7eb-59c1-863e-25e1cc85ef6c', 'en', $h$For which pipe diameters is it suitable?$h$, $h$<div> <p>Thanks to bandages of various widths, it can be used on pipe diameters from 25 mm up to 600 mm.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('9e44cbce-fcc0-5333-8dfd-ec564818b9c2', '92bc84e5-81ec-5e8e-a036-a9084c8551d4', 'en', $h$How is it applied?$h$, $h$<div> <p>After the damaged area is cleaned, the bandage is wrapped and pressure is applied over it; it hardens in a short time.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('29fe96a3-73ce-5896-8d66-1cfc4c181ca7', '46f27085-ba12-5e21-a5e0-97fcc6ec11fb', 'en', $h$On which pipe types can it be used?$h$, $h$<div> <p>It can be used safely on water, oil, fuel and most industrial fluid lines.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('af536285-338c-56d7-bb68-fed1b9d63960', '97d52c9e-efec-5786-8e65-ed989fa790f0', 'en', $h$Marine Chemicals$h$, $h$marine-chemicals$h$, $h$Marine Chemicals – Professional Solutions for Shipping and Marine Applications$h$, $h$<div> <p>The HD Marine marine chemicals category includes <strong>chemical products specially formulated for ship maintenance, cleaning, protection and improving operational performance in the maritime sector</strong>. These products cover a wide range of uses, from ship surface maintenance to fuel and oil systems, from ship cleaning to environmental protection applications.</p><p>Delivering high performance under demanding conditions at sea, marine chemicals provide reliable solutions for both commercial vessels and yacht/boat owners.</p> </div><div> <p>HD Marine marine chemicals are used for the following purposes:</p><ul><li>🛥️ <strong>Ship surface cleaning and polishing</strong></li><li>🛠️ <strong>Engine, fuel and oil system maintenance</strong></li><li>🛡️ <strong>Corrosion-inhibiting and rust-dissolving applications</strong></li><li>♻️ <strong>Wastewater treatment and environmental protection support products</strong></li><li>⛽ <strong>Fuel additives and performance enhancers</strong></li></ul><p>These products are formulated to suit the characteristics of the marine environment and offer <strong>high effectiveness with low environmental impact</strong>.</p> </div><div> <p>✔ Optimized for maritime conditions<br/>✔ Highly effective formulation<br/>✔ Non-abrasive, safe use<br/>✔ Environmentally friendly alternatives available<br/>✔ Compliant with industrial and marine standards</p> </div><div> <ul><li><strong>Ship surface cleaners</strong> – Salt water, oil and dirt removers</li><li><strong>Engine and machinery maintenance chemicals</strong> – Protective oils, rust removers</li><li><strong>Fuel additives</strong> – Performance and fuel efficiency enhancers</li><li><strong>Antifreeze and water removers</strong> – Freezing, moisture and corrosion prevention</li><li><strong>Wastewater and environmental products</strong> – Treatment chemicals compliant with environmental standards</li></ul><p>Each product category delivers professional results aimed at optimizing ship maintenance processes and increasing operational efficiency.</p> </div>$h$, NULL, $h$Marine Chemicals | HD Marine$h$, $h$The HD Marine marine chemicals category includes chemical products specially formulated for ship maintenance, cleaning, protection and improving…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('f8756013-b676-583f-b8b0-1c3cfb44e4e5', 'af4337f1-6553-5905-94d2-5beb2265ead5', 'en', $h$What are marine chemicals used for?$h$, $h$<div> <p>Marine chemicals are specially formulated products for cleaning, maintenance, surface protection and improving system performance in the marine environment.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('028b3b52-8b28-501e-94fe-412e4fef4909', '8c3471c7-bf39-5601-95f3-455d1900b287', 'en', $h$Which marine chemicals are available?$h$, $h$<div> <p>Various categories are available, such as surface cleaners, engine maintenance products, fuel additives, rust dissolvers and environmental products.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('8e210d48-6919-5531-a6aa-aa6c79312d13', 'ae2bccbe-28ac-5252-af69-63ca483e6ef6', 'en', $h$Is it safe to use in a marine environment?$h$, $h$<div> <p>HD Marine products are formulated for safe use in compliance with maritime standards.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5d1e7bc3-5f54-5ef3-9289-94747f03a264', '43f9eedf-b3fb-5af2-867b-a9becee5cb1a', 'en', $h$Are the chemicals environmentally friendly?$h$, $h$<div> <p>Many products have environmentally friendly formulations compliant with environmental standards.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('c049a024-5054-5e36-9d32-c35ebe623b4a', '0a28d2bd-c819-5452-a7f5-8f39aee0b28b', 'en', $h$Thermal Label$h$, $h$thermal-label$h$, $h$Temperature Indicator Labels – Instant and Permanent Heat Monitoring Solutions$h$, $h$<div> <p><strong>Temperature indicator labels</strong> are practical and reliable measurement solutions that provide temperature monitoring by changing color or leaving a permanent mark when a specific temperature level is reached. They operate without requiring electronic sensors and offer fast checks particularly on <strong>industrial equipment, pipelines, motors, electrical panels and in shipping processes</strong>.</p><p>HD Marine temperature indicator labels are an effective solution for <strong>overheating detection</strong>, <strong>process control</strong>, <strong>maintenance planning</strong> and <strong>transport safety</strong>.</p> </div><div> <p>These labels:</p><ul><li>Activate within a predetermined temperature range</li><li>Provide a visual warning by changing color</li><li>Can be single-use (irreversible) or multi-level</li><li>Require no external power source</li></ul><p>They are used as an early warning mechanism, particularly in systems at risk of overheating.</p> </div>$h$, $h$<div> <p>Temperature indicator labels are used for <strong>instant heat monitoring and overheating detection</strong> particularly in areas such as:</p><ul><li>Electrical panels</li><li>Motor and gearbox systems</li><li>Steam lines</li><li>Industrial machinery</li><li>Transport and logistics (temperature-controlled products)</li><li>Marine engine rooms</li></ul> </div><div> <p>✔ Requires no electronic sensors<br/>✔ Easy application (stick and use)<br/>✔ Low-cost temperature monitoring<br/>✔ Visual and fast inspection capability<br/>✔ Provides early warning in maintenance processes</p> </div>$h$, $h$Thermal Label | HD Marine$h$, $h$Temperature indicator labels are practical and reliable measurement solutions that provide temperature monitoring by changing color or leaving a permanent…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('3670aa70-0217-5aff-b19c-84e48768fdae', 'dcbd8da3-4c06-58d2-8c6b-b3a7ccc0bdae', 'en', $h$How does a temperature indicator label work?$h$, $h$<div> <p>When the defined temperature level is reached, it changes color through a chemical reaction and leaves a permanent mark.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('4007ecba-2847-55c0-b006-fb76b53ba671', 'd3611b2a-b157-5fed-9a4e-71b01f15d7bd', 'en', $h$Can it be reused?$h$, $h$<div> <p>It is generally single-use; once the temperature threshold is exceeded, an irreversible color change occurs.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('4cba5cde-42e3-5b98-99bd-d7e6170d69ed', '12311967-9831-583a-a128-ce2a68340bd0', 'en', $h$Where can it be used?$h$, $h$<div> <p>It can be used on motors, panels, pipelines, shipping boxes and heat-sensitive equipment.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('2a72e0a8-8456-5bde-8cfc-95927588fbed', '2dfaa1a6-6b7d-5d57-8095-c3ae02046018', 'en', $h$In which temperature range does it operate?$h$, $h$<div> <p>Depending on the model, different threshold options are available from 30°C up to 260°C.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('85f4f7de-a0f3-5880-82a7-3e46c9111425', '1de0cabb-27b9-535f-9f93-44acfa779898', 'en', $h$Industrial Chemicals$h$, $h$industrial-chemicals$h$, NULL, $h$<div> <p>Metal surface treatment chemicals play a critical role in the <strong>cleaning, preparation, protection and coating</strong> processes of metal surfaces in industrial applications. The high-performance chemical solutions we offer at HD Marine increase production efficiency while raising surface quality to the maximum level.</p><p>Our broad product portfolio has been specially developed for <strong>oil, dirt and oxide removal</strong>, surface activation, corrosion protection and pre-coating preparation processes. It can be used safely on different surface types, including iron and steel, stainless steel, aluminum and alloyed metals.</p> </div><div> <p>Cleaning chemicals used in preparing metal surfaces before coating or assembly ensure the effective removal of all unwanted residues from the surface.</p> </div><div> <ul><li>Industrial oil and grease removers</li><li>Alkaline and acidic cleaners</li><li>Rust and oxide removers</li><li>Pre-phosphate surface preparation chemicals</li><li>Solvent-based and water-based cleaners</li></ul> </div><div> <ul><li>High cleaning performance</li><li>Effective results without damaging the surface</li><li>Excellent surface preparation before coating</li><li>Time and cost savings in work processes</li></ul> </div><div> <p>Coating chemicals protect metal surfaces against external factors while also imparting aesthetic and functional properties.</p> </div><div> <ul><li>Phosphating chemicals (zinc, iron, manganese)</li><li>Passivation and protective coating products</li><li>Corrosion-inhibiting chemicals</li><li>Pre-paint surface preparation chemicals</li><li>Temporary protective film and coating solutions</li></ul> </div><div> <ul><li>Long-term corrosion resistance</li><li>Improved coating and paint adhesion performance</li><li>Durability under demanding industrial conditions</li><li>Achieving a homogeneous, high-quality surface</li></ul> </div><div> <ul><li>Shipping and ship maintenance-repair</li><li>Iron-steel and metalworking industry</li><li>Automotive and supplier industry</li><li>Chemical and process industries</li><li>Energy and heavy industry facilities</li></ul> </div><div> <ul><li>Products meeting high quality standards</li><li>Formulation options tailored to different processes</li><li>Fast supply and competitive price advantage</li><li>Technical consultancy and field support</li></ul> </div>$h$, NULL, $h$Industrial Chemicals | HD Marine$h$, $h$Metal surface treatment chemicals play a critical role in the cleaning, preparation, protection and coating processes of metal surfaces in industrial…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('7b4cf80d-f58b-581e-b0b3-e32c236af0e1', '64f700b2-09bd-5e50-8ae0-e0b6fffb5c51', 'en', $h$Sine Lobe Pump$h$, $h$sine-lobe-pump$h$, $h$Lobe Pump – High-Efficiency Positive Displacement Transfer$h$, $h$<div> <p>A <strong>lobe pump (rotary lobe pump)</strong> is a type of positive displacement pump consisting of lobed rotors. Thanks to this design, it provides <strong>low shear, high efficiency and precise flow control</strong>. Sine lobe pumps are the ideal solution for handling <strong>viscous liquids, particle-laden fluids and delicate products</strong> without problems.</p><p>HD Marine sine lobe pumps, with their durable body construction and superior performance, deliver <strong>uninterrupted liquid transfer</strong> in industrial facilities, marine applications and production lines.</p> </div><div> <ul><li>🌟 <strong>High performance:</strong> Constant flow rate and low energy consumption</li><li>⚙ <strong>Product safety:</strong> Low shear preserves product structure</li><li>🧰 <strong>Easy maintenance:</strong> Fast cleaning and maintenance after use</li><li>🏭 <strong>Broad application compatibility:</strong> Food, chemicals, marine and industry</li></ul> </div>$h$, $h$<div> <p>HD Marine lobe pumps are preferred particularly in the following sectors:</p><ul><li><strong>Food and beverage production</strong> (e.g. syrups, sauces)</li><li><strong>Chemical and pharmaceutical processes</strong></li><li><strong>Wastewater and filtration systems</strong></li><li><strong>Paint, ink and solvent transfer lines</strong></li><li><strong>Marine and industrial applications</strong></li></ul><p>The breadth of application areas makes sine lobe pumps highly versatile.</p> </div>$h$, $h$Sine Lobe Pump | HD Marine$h$, $h$A lobe pump (rotary lobe pump) is a type of positive displacement pump consisting of lobed rotors. Thanks to this design, it provides low shear, high…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d5fdda09-48f3-56c6-9f97-3914607ff227', '63022ab7-668d-5da7-9d44-9fc07d1d7a9d', 'en', $h$What is a lobe pump?$h$, $h$<div> <p>It is a type of pump operating with positive displacement lobed rotors, providing liquid transfer at a constant flow rate.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('88473e90-6138-58de-b67d-62aecf3a12d3', '915a0f68-53e5-534f-acf8-682e663f496c', 'en', $h$With what kinds of liquids is it used?$h$, $h$<div> <p>It is used with fluids requiring delicate transfer, such as viscous liquids, particle-laden fluids, food products and chemicals.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c652adca-faa7-56e0-9240-2e6fd99725c6', '5edefd86-e423-5dec-a45b-b8443cd0ee1e', 'en', $h$What is the advantage of a lobe pump?$h$, $h$<div> <p>With low shear, it minimizes product degradation and provides constant flow.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5e5e14df-af3a-51b4-a4d4-6eea292727d8', '8cb1f7a2-a4a9-581b-828b-f17489b304c9', 'en', $h$Who should choose it?$h$, $h$<div> <p>Food, pharmaceutical and chemical production plants, and all industrial applications requiring delicate fluid transfer.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('b6a7676d-696e-5dc1-a2e3-10445334909f', '44df010c-1660-55c7-bd46-dea732e01d1c', 'en', $h$Anti Splashing Tape$h$, $h$anti-splashing-tape$h$, $h$Anti Splashing Tape – Sealing and Splash Prevention Tape$h$, $h$<div> <p><strong>Anti Splashing Tape</strong> is a high-performance sealing tape designed to prevent <em>liquid splashing</em>, <em>leakage</em> and <em>contamination</em> at pipe connections, joints and vibrating surfaces. It is used particularly in marine, industrial and maritime applications. Thanks to its durable structure, it provides long-lasting protection.</p><p>HD Marine Anti Splashing Tape is an <strong>easy-to-apply</strong> solution <strong>resistant to water, oil and chemical splashes</strong>, providing safe sealing at connection points requiring maintenance.</p> </div><div> <p>✔ <strong>Highly resistant sealing</strong> – Protects against water, oil and chemical splashes<br/>✔ <strong>Flexible and durable structure</strong> – Effective performance even under vibration<br/>✔ <strong>Easy application</strong> – Fast installation in tape form<br/><span>✔</span> <strong>Broad compatibility</strong> – On pipe connection elements and mounting surfaces<br/>✔ <strong>Long-lasting use</strong> – Resistant to wear and deformation</p> </div>$h$, $h$<div> <p>Anti Splashing Tape offers an effective sealing solution particularly in:</p><ul><li><strong>Pipe joints and connections</strong></li><li><strong>Surfaces subject to machine vibration</strong></li><li><strong>Marine engine rooms</strong></li><li><strong>Industrial facility lines</strong></li><li><strong>Splash and leak prevention in oil / fuel / water systems</strong></li></ul><p>and similar applications.</p> </div>$h$, $h$Anti Splashing Tape | HD Marine$h$, $h$Anti Splashing Tape is a high-performance sealing tape designed to prevent liquid splashing , leakage and contamination at pipe connections, joints and…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5d40d304-ea80-54b8-bb8e-27bd101f8c45', '017c10f6-220d-5a7a-85f4-01dd686951f5', 'en', $h$What is Anti Splashing Tape?$h$, $h$<div> <p>Anti Splashing Tape is a highly resistant sealing tape used to prevent splashing and leakage at pipe connections.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('fc03307c-6201-543f-b4c5-51a6173953dd', '43476fcd-d2d1-580c-a37e-f3e3a14bb6e3', 'en', $h$On which surfaces is it used?$h$, $h$<div> <p>It is used on pipe connections, assembly joints and vibrating surfaces.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c9c2be31-e3bc-5fd1-aba2-0d1fe563c4cc', 'c68b65e4-5714-5ad4-afdc-f92467e4ccee', 'en', $h$To which fluids is it resistant?$h$, $h$<div> <p>Thanks to its material structure resistant to water, oil and mild chemical splashes, it provides safe sealing.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('698d79bd-3ad7-53ad-a9fb-f5f7d20feb4e', '0840a7d6-e6ee-5208-8abd-8f89df366c6f', 'en', $h$Is it difficult to apply?$h$, $h$<div> <p>No, thanks to its tape form it is applied easily; no special tools are required.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('8319b30c-7d58-5f4f-8c1b-0debdddeb2af', '4ae6c6bb-a58e-5a16-866b-622cb26d9c6d', 'en', $h$Wilden® Compatible Spare Parts$h$, $h$wilden-compatible-spare-parts$h$, $h$Wilden® Compatible Spare Parts$h$, $h$<div> <div><p>WILDEN PUMP, one of the pioneering companies in its field, having developed the first compressed-air-operated diaphragm pumps in 1955, has held a leading position in the air-operated double diaphragm pump market from the very beginning. Since 1998, as part of the Dover Group, it has continued to rise, standing apart from its competitors in product variety and technology. HD Marine, since its founding, has worked with leading companies and manufacturers. It offers its customers suitable equipment and products in line with their needs, pump and spare part support, after-sales support, engineering services, and procurement and installation processes.</p></div> </div><div> <div><p>For Air-Operated Double Diaphragm Pumps, you can find many Wilden-brand-compatible spare parts you may need at HD Marine, such as diaphragms, seats, balls, pistons, gaskets, air valves, O-rings, hardware, clamp bands, mufflers and repair kits.</p><p>Wilden Type pump and spare part support is provided to the user in line with requirements and according to different places of use. One of the most important features of Wilden Type pumps is that they operate with energy-saving air distribution technology and, with a wide range of material options, are models that perform successfully in high-pressure applications without stalling or freezing.</p><p>Wilden Type pumps are divided into four main categories according to their areas of use: Metal-Bodied Air-Operated Double Diaphragm Pumps, Plastic-Bodied Air-Operated Double Diaphragm Pumps, Metal-Bodied High-Pressure Pumps, and Plastic Magnetically Coupled Centrifugal Pumps. Outside this group, Wilden Type pumps and spare parts used in different fields such as food applications and mining applications are also available.</p><p>The areas where Wilden Type pumps and spare parts are used generally include various applications such as alcohol, chemical treatment, acid / alkali / chemical, paint and pigment, drainage applications, petroleum-derived liquids, ceramic slip, glaze, and oil and solvent transfer.</p></div> </div>$h$, NULL, $h$Wilden® Compatible Spare Parts | HD Marine$h$, $h$WILDEN PUMP, one of the pioneering companies in its field, having developed the first compressed-air-operated diaphragm pumps in 1955, has held a leading…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('86fffe23-6ebe-5020-aadd-0998f9eee98b', 'a3abca29-00e2-5a6a-86ee-eb9f4c2cb152', 'en', $h$Aro® Compatible Spare Parts$h$, $h$aro-compatible-spare-parts$h$, $h$Aro® Compatible Spare Parts$h$, $h$<div> <div><p>Aro® first launched its air-operated double diaphragm pump product in the eighties in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand Corp. and is one of the leading AODD Pump brands.</p></div> </div><div> <div><p>ARO® air-operated diaphragm pumps have the capacity to handle a variety of viscous fluids and ensure non-stalling, ice-free operation. The unbalanced air valve design prevents the stalling problems associated with other pumps. Quick-dump exhaust valves direct cold exhaust air away from ice-prone components and prevent freezing. Depending on the type of liquid to be discharged, piston pump packages are available with multiple configurations for the pump section, including single-body, two-body or heavy-duty two-body designs.</p><p>ARO® diaphragm pumps, with their cost-effectiveness and reliable construction, are a good choice for industrial and chemical applications. The bolted, leak-free design eliminates cross-contamination and increases operator safety. The modular design, reduced part count and easy-to-use repair kits also minimize product repair time when needed.</p><p>HD Marine brings you reliable, quality products with spare parts compatible with double diaphragm (AODD) Pumps. HD Marine provides spare product support for many parts according to your preference, and is an address where you can find Aro spare parts such as <strong>valve balls, valve seats, diaphragms, gaskets, clamp bands, mufflers, pistons and valve rings</strong>.</p><p>In the event of any failure or maintenance need for Diaphragm Pumps, you can select Aro-brand-compatible products individually through the HD Marine site, or from the <strong>Aro Service Kits</strong> section you can access a service/repair kit containing screws, gaskets and many ring varieties together. Service kits come in two types: a wet kit for the wet side of your pneumatic double diaphragm pump, and a kit used for the maintenance and repair of the air side of your air-operated double diaphragm pump. Since these two kits contain different products, you should make your choice by considering which products you need and in which area you will use them.</p><p>Apart from <strong>Aro Service Kits</strong>, when you want to purchase products individually, you can also find <strong>Aro gaskets, Aro rings, Aro valve balls, Aro valve seats, Aro hardware and Aro diaphragms</strong>. However, it should be kept in mind that the area in which each industry uses its pumps, and the appropriate Aro spare part product for that area, will vary. According to your specific application needs such as chemical compatibility, temperature and sealing capacity, HD Marine offers its customers the most widely used and preferred quality materials and products in pump parts, such as <strong>Santoprene, Hytrel, N-fit, PTFE and Neoprene</strong>.</p></div> </div>$h$, NULL, $h$Aro® Compatible Spare Parts | HD Marine$h$, $h$Aro® first launched its air-operated double diaphragm pump product in the eighties in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('ef8436d4-8d14-596c-ac47-9f22768be136', '160e4b7f-4479-5c48-a2da-27d2c4277745', 'en', $h$Sandpiper® Compatible Spare Parts$h$, $h$sandpiper-compatible-spare-parts$h$, $h$Sandpiper® Compatible Spare Parts$h$, $h$<div> <div><p>HD Marine delivers to its users the highest-quality spare parts compatible with the Sandpiper® brand. It has a complete, wide range of wear parts for Air-Operated Double Diaphragm Pumps, such as diaphragms, seats, balls, pistons, gaskets, air valves, O-rings, hardware, clamp bands, shafts, mufflers and repair kits.</p></div> </div><div> <div><p>The <strong>Sandpiper® air valve</strong> is one of the main elements of an Air-Operated Double Diaphragm pump. Sandpiper pumps use both internal air valve and external air valve designs and locations. The materials used in the air valve body can vary in quality, such as brass, aluminum, plastic or stainless steel. In <strong>diaphragm pumps, the air valves</strong> are positioned between the diaphragms, right at the center of the pump. In this way, air passages and dead volumes are reduced to a minimum. HD Marine also provides its customers with the highest-quality spare part support compatible with Sandpiper.</p><p>A diaphragm pump operates on compressed air. The functional operation of the <strong>valve seats</strong> and <strong>valve balls</strong>, moving back and forth to pump the liquid, is what makes it work. Valve seats and valve balls are critical components for the proper operation of an air-operated double diaphragm pump. <strong>Valve balls and valve seats in Air-Operated Double Diaphragm Pumps</strong> are found in many sectors such as aerospace, environment, energy, automotive, construction, chemicals, ceramics, cosmetics, food and beverage, oil and gas, packaging, steel and metals, and pharmaceuticals.</p><p>As an important part of the general maintenance program, <strong>diaphragms</strong> should be replaced at regular intervals according to the manufacturer's recommendations. A double diaphragm pump uses two flexible diaphragms connected to each other by a shaft moving back and forth, and is also known as a positive displacement pump. The role of the diaphragms is to operate in a way that separates the air on one side from the medium on the other side.</p><p>For questions or problems regarding the <strong>valve seats, valve balls, air valve, diaphragm</strong> or <strong>hardware</strong> of your Air-Operated Double Diaphragm Sandpiper Pump, please contact our professional team members working in HD Marine spare Pump Parts. We would be happy to assist you and reach a solution for your issues with spare parts compatible with Sandpiper-brand products.</p></div> </div>$h$, NULL, $h$Sandpiper® Compatible Spare Parts | HD Marine$h$, $h$HD Marine delivers to its users the highest-quality spare parts compatible with the Sandpiper® brand. It has a complete, wide range of wear parts for…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('aeee2f47-c511-5275-8464-22ccf5b2e087', '53075258-51b5-56e5-9573-f2ed7e9c2540', 'en', $h$Blagdon® Compatible Spare Parts$h$, $h$blagdon-compatible-spare-parts$h$, $h$Blagdon® Compatible Spare Parts$h$, $h$<div> <p>HD Marine serves its customers with spare parts compatible with Blagdon products, in varieties made of materials that change according to the area of use. Diaphragm pumps are used in various applications such as alcohol, chemical treatment, acid / alkali / chemical, paint and pigment, drainage applications, petroleum-derived liquids, ceramic slip, glaze, and oil and solvent transfer. At HD Marine you can find various Blagdon spare part products such as valve balls, valve seats, diaphragms, hardware, rings, gaskets and repair kits.</p> </div><div> <p>In a diaphragm pump's operation on compressed air and in pumping the liquid, the valve seats and valve balls have an important function, moving back and forth. For the pump to operate properly, every part used must be of high quality, robust and made of material suitable for the area in which it will be used. For example, <strong>Valve Ball Neoprene Fit Blagdon Pumps Parts</strong> should be used for non-aggressive liquid applications; <strong>Valve Ball PTFE Fit Blagdon Pumps Parts</strong> when pumping aggressive liquids; <strong>Valve Ball BUNA-N/Nitrile Fit Blagdon Pumps Parts</strong> when pumping petroleum oil-based liquids; <strong>Valve Ball FKM Fit Blagdon Pumps Parts</strong> for liquids such as aggressive acids requiring extreme temperatures; and <strong>Valve Ball EPDM/ Blagdon Pumps Parts</strong> materials for dilute acids requiring extreme cold. Although Blagdon balls products look similar in appearance, their material and color code change according to the area in which they will be used.</p><p>HD Marine also offers material options in Blagdon diaphragm spare part products. The most widely used materials, in varieties such as Neoprene, EPDM, Nitrile and PTFE, reach customers in different sizes and with color codes. Through the HD Marine site you can access the <strong>Blagdon Valve Ball and Blagdon Diaphragm</strong> spare parts you need and review the products. For your questions and requests, you can reach our professional colleagues in the field and obtain information about Blagdon spare part varieties.</p> </div>$h$, NULL, $h$Blagdon® Compatible Spare Parts | HD Marine$h$, $h$HD Marine serves its customers with spare parts compatible with Blagdon products, in varieties made of materials that change according to the area of use…$h$, 'auto') ON CONFLICT DO NOTHING;
